raw.css:
:root {
  --color-primary: #1a472a;
  --color-primary-light: #2d6e47;
  --color-accent: #d4a373;
  --color-accent-on-dark: #e8c4a0;
  --color-bg: #faf8f3;
  --color-bg-alt: #f0ebe1;
  --color-text: #1a1a1a;
  --color-text-light: #5a5a5a;
  --color-text-inverse: #ffffff;
  --color-border: #d9d0c4;
  --color-success: #2d6e47;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-primary);
}

h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  margin-bottom: var(--spacing-md);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  margin-bottom: var(--spacing-lg);
}

h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-light);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: border-color 0.2s ease, color 0.2s ease;
}

a:hover {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding-left: var(--spacing-lg);
  padding-right: var(--spacing-lg);
}

.site-header {
  background-color: var(--color-primary);
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  border-bottom: 3px solid var(--color-accent);
}

.logo {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 4vw, 1.75rem);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-text-inverse);
  border: none;
}

.logo:hover {
  color: var(--color-accent-on-dark);
  border: none;
}

.logo:focus {
  outline: 3px solid var(--color-accent-on-dark);
  outline-offset: 4px;
}

.site-footer {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  padding-top: var(--spacing-2xl);
  padding-bottom: var(--spacing-2xl);
  margin-top: var(--spacing-2xl);
}

.site-footer p {
  margin-bottom: var(--spacing-md);
  font-size: 0.95rem;
}

.site-footer a {
  color: var(--color-accent-on-dark);
  border-bottom-color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  color: var(--color-text-inverse);
  border-bottom-color: var(--color-text-inverse);
}

button, .btn {
  display: inline-block;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-md);
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var(--color-primary);
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
  text-decoration: none;
}

button:hover, .btn:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-light);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

input[type="email"],
input[type="text"],
input[type="number"],
textarea,
select {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background-color: var(--color-text-inverse);
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type="email"]:focus,
input[type="text"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(26, 71, 42, 0.1);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

card {
  background-color: var(--color-text-inverse);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(26, 71, 42, 0.08);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

article {
  background-color: var(--color-text-inverse);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(26, 71, 42, 0.08);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

article:hover {
  box-shadow: 0 4px 16px rgba(26, 71, 42, 0.12);
  transform: translateY(-2px);
}

article h3 {
  margin-top: 0;
}

.tag {
  display: inline-block;
  font-size: 0.85rem;
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 20px;
  margin-right: var(--spacing-xs);
  margin-bottom: var(--spacing-xs);
}

.meta {
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

@media (max-width: 600px) {
  :root {
    --spacing-lg: 1rem;
    --spacing-xl: 1.5rem;
    --spacing-2xl: 2rem;
  }

  .container {
    padding-left: var(--spacing-md);
    padding-right: var(--spacing-md);
  }

  h1 {
    font-size: 1.5rem;
  }

  h2 {
    font-size: 1.25rem;
  }

  .grid {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 601px) {
  .container {
    padding-left: var(--spacing-lg);
    padding-right: var(--spacing-lg);
  }
}

